package com.cryptoloan.notification.adapters.out;import com.cryptoloan.notification.domain.port.out.NotificationPorts.EmailSender;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Component;@Component class SmtpEmailAdapter implements EmailSender{private final JavaMailSender sender;private final String from;SmtpEmailAdapter(JavaMailSender sender,@Value("${cryptoloan.mail.from}")String from){this.sender=sender;this.from=from;}public void send(String recipient,String subject,String message){SimpleMailMessage mail=new SimpleMailMessage();mail.setFrom(from);mail.setTo(recipient);mail.setSubject(subject);mail.setText(message);sender.send(mail);}}

